-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- The cloud database was provisioned without lms.update_updated_at_column()
-- and its four updated_at triggers (20260101000012), which later migrations
-- depend on (20260927141654 alters the function; Phase 2 attaches a trigger).
-- Idempotent: a no-op wherever they already exist (e.g. local installs).
BEGIN;
CREATE OR REPLACE FUNCTION lms.update_updated_at_column()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$;

DO $repair$
DECLARE
  target text;
BEGIN
  FOREACH target IN ARRAY ARRAY['users', 'learner_profiles', 'modules', 'learner_progress'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_trigger
        WHERE tgrelid = format('lms.%I', target)::regclass
          AND tgname = format('update_%s_updated_at', target) AND NOT tgisinternal) THEN
      EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON lms.%I FOR EACH ROW EXECUTE FUNCTION lms.update_updated_at_column()',
        'update_' || target || '_updated_at', target);
    END IF;
  END LOOP;
END;
$repair$;
COMMIT;
